def parse_fields(text):
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '\\' and i + 1 < n:
            # Skip the backslash; the next character is literal
            # It belongs to the current field being built
            if result and result[-1] == '':
                # Just add the literal char to the empty field
                result[-1] += text[i + 1]
            else:
                # Start a new field with the literal char
                result.append(text[i + 1])
            i += 2
        elif text[i] == ',':
            # End of current field
            result.append('')
            i += 1
        else:
            # Accumulate characters until comma or end
            start = i
            while i < n and text[i] != ',':
                i += 1
            if i < n:
                result.append(text[start:i])
            else:
                # End of string, append the accumulated part
                result.append(text[start:i])

    return result
